from dsl import *

modul("E", "Vertrieb und Kommunikation", "Zielkunden, Einwände, E-Mails, Kundenbetreuung und Auftreten")

stapel("t26", "E", "Zielkunden und Vertrieb",
    "Leads prüfen, Entscheider verstehen, der Weg vom Lead zum Kunden.", [
    P("t26-05", "Ordne den Entscheidern ihren typischen Fokus zu.",
      [["CEO / Gründer", "Strategie, Geschäftsmodell, Wirtschaftlichkeit"], ["Head of Sales / Wholesale", "Kanalmix und Ergänzung zum Wholesale"], ["Head of E-Commerce", "Internationalisierung und Ressourcen"], ["Marketplace Manager", "Operative Skalierung, Daten, SLAs"]],
      "Mit dem Gründer sprichst du über das Geld, mit dem Marketplace Manager über Abläufe.", quelle="Allgemeinwissen Vertrieb"),
    M("t26-06", "Welche Signale deuten darauf hin, dass eine Marke Bedarf haben könnte? Kreuze alles Richtige an.",
      ["Neue Marktplatz-Listings oder neue Länder im Shop", "Stellenanzeigen für Marketplace oder E-Commerce Operations", "Finanzierungs-, Übernahme- oder Expansionsnews", "Häufige Kritik in Bewertungen zu Lieferung oder Retouren"],
      ["Der Geschäftsführer hat Geburtstag", "Die Marke hat einen neuen Praktikanten"],
      "Solche Intent-Signale helfen, die richtigen Firmen zur richtigen Zeit anzusprechen.", quelle="Allgemeinwissen Vertrieb"),
    M("t26-08", "Was prüfst du, bevor ein Lead weiterverfolgt wird? Kreuze alles Richtige an.",
      ["Ist die Ware lieferbar?", "Gibt es SKUs und Produktbilder?", "Wo verkauft die Marke schon, als Seller oder Vendor?", "Passen Kategorie und Preis?", "Ist die Marke bereit, bei HBOD einzulagern?"],
      ["Wie groß ist das Büro der Marke?", "Welche Automarke fährt der Geschäftsführer?"],
      "Erst prüfen, ob es grundsätzlich passt, dann Zeit investieren.", quelle="Gespräch mit Kollegen (Erfahrungswert), Erfahrung aus Kundenmails (anonymisiert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t26-09", "Welche Voraussetzung muss jede neue Marke für die HBOD-Marktplätze erfüllen?",
      ["Die Bereitschaft, die Ware für HBOD-Kanäle vollständig im HBOD-Lager einzulagern", "Ein Instagram-Account mit 1 Mio. Followern", "Ein Sitz in Nordrhein-Westfalen", "Mindestens 1.000 SKUs"],
      "HBOD nutzt für die Marktplätze ausschließlich das eigene Lager. Weil HBOD selbst als Verkäufer auftritt und an die Lieferzeiten der Marktplätze gebunden ist, braucht HBOD die Kontrolle über das Fulfillment.", quelle="Unternehmenspräsentation 2026, Erfahrung aus Kundenmails (anonymisiert)"),
    R("t27-04", "Bringe die Phasen des Sales-Prozesses in die richtige Reihenfolge.",
      ["Lead", "Qualifizierung", "Erstkontakt", "Bedarf verstehen", "Angebot", "Verhandlung", "Abschluss", "Onboarding", "Entwicklung (Cross- und Upselling)"],
      "Im CRM siehst du, in welcher Phase jeder Kontakt steht und was der nächste Schritt ist.", quelle="Allgemeinwissen Vertrieb"),
    S("t27-09", "Wann ist ein guter Moment, um einen Bestandskunden nach einer Empfehlung zu fragen?",
      ["Nach einem Erfolgsmoment, z. B. einem guten Monatsergebnis oder einem positiven Business Review", "Direkt nach einer Beschwerde", "Wenn die Abrechnung negativ war", "Im ersten Gespräch vor Vertragsschluss"],
      "Zufriedene Kunden empfehlen am liebsten, wenn der Nutzen gerade sichtbar ist.", quelle="Allgemeinwissen Vertrieb"),
    S("t27-11", "Was ist Upselling bzw. Cross-Selling bei Bestandskunden von HBOD?",
      ["Weitere Marken der Firma, weitere Marktplätze oder Länder dazunehmen", "Den Kunden zu einem teureren Vertrag zwingen", "Die Provision erhöhen", "Dem Kunden Ware verkaufen"],
      "Beispiel: Eine Firma mit mehreren Marken bringt nach der ersten Marke weitere zu HBOD.", quelle="Allgemeinwissen Vertrieb"),
    S("t27-12", "Warum solltest du Vertragsfristen jedes Kunden im CRM festhalten?",
      ["Damit du rechtzeitig vor Verlängerungen und Kündigungsfristen mit dem Kunden sprichst", "Weil das Finanzamt es verlangt", "Weil Marktplätze danach fragen", "Das ist unwichtig"],
      "Ein gutes CRM zeigt Status, nächsten Schritt und Verantwortlichen.", quelle="Allgemeinwissen Vertrieb"),
],
    punkte=["Vor dem Erstkontakt prüfen: Ist die Ware lieferbar, gibt es SKUs und Bilder, wo verkauft die Marke schon, passen Kategorie und Preis, will sie bei HBOD einlagern?", "Entscheider: Gründer (Strategie und Geld), Sales (Kanalmix), E-Commerce (Internationalisierung), Marketplace Manager (Abläufe, Daten, SLAs).", "Signale für Bedarf: neue Marktplätze oder Länder, Stellenanzeigen, Expansionsnews, Kritik an Lieferung oder Retouren.", "Der Weg: Lead, Qualifizierung, Erstkontakt, Bedarf verstehen, Angebot, Verhandlung, Abschluss, Onboarding, Entwicklung.", "Empfehlungen nach Erfolgsmomenten erfragen. Upselling über weitere Marken, Marktplätze oder Länder."],
    merksatz="Erst qualifizieren, dann Zeit investieren.",
    quelle="Allgemeinwissen Vertrieb, Gespräch mit Kollegen (Erfahrungswert)")

stapel("t28", "E", "Einwände souverän beantworten",
    "Typische Einwände von Marken und wie du ruhig, ehrlich und überzeugend reagierst.", [
    S("t28-01", "Ein Kunde schreibt: \"Eure Logistikkosten von 2,07 € sind viel zu hoch.\" Was ist die beste Reaktion?",
      ["Einordnen: Der Wert gilt je Warenkorb und umfasst Pick, Verpackung, Wareneingang und Lager. Bundles senken die Kosten deutlich.", "Sofort einen Rabatt versprechen", "Sagen, dass andere noch teurer sind, ohne Beleg", "Das Thema übergehen"],
      "Ruhig erklären, Vergleich fair machen und einen Hebel anbieten.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t28-02", "Ein Kunde sagt: \"Eure Provision kommt ja noch zu den Marktplatzgebühren dazu.\" Was ist die beste Reaktion?",
      ["Erklären, was die Provision abdeckt (Aufschaltung, Content, Preise, Service, Steuer, Kampagnen), dass es keine Fixkosten gibt und HBOD nur bei Erfolg verdient", "Die Provision kleinreden", "Behaupten, die Marktplätze seien kostenlos", "Die Provision spontan halbieren"],
      "Die Marktplatzprovisionen gibt HBOD 1:1 weiter. Die HBOD-Provision ist nicht verhandelbar.", quelle="Unternehmenspräsentation 2026, Einweisung Produktkalkulation"),
    S("t28-03", "Ein Kunde sagt: \"Beim Fachhandel bekommen wir pro Stück mehr.\" Was ist die beste Reaktion?",
      ["Anerkennen, dass HBOD den Fachhandel ergänzt statt ersetzt, und auf Zusatzumsatz in neuen Kanälen und Ländern sowie auf Hebel wie Multipacks hinweisen", "Sagen, dass der Fachhandel bald ausstirbt", "Den Fachhandel schlechtmachen", "Behaupten, HBOD zahle immer mehr als der Fachhandel"],
      "Ergänzen, nicht ersetzen: HBOD bringt Zusatzumsatz in Kanälen und Ländern, die der Fachhandel nicht erreicht.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t28-04", "Ein Kunde fragt: \"Können wir aus unserem eigenen Lager liefern?\" Was antwortest du?",
      ["Für die HBOD-Kanäle nein, weil HBOD als Verkäufer für die Lieferzeiten der Marktplätze haftet und deshalb die Kontrolle über das Fulfillment braucht", "Ja, kein Problem", "Vielleicht, wir schauen mal", "Nein, weil wir an der Logistik verdienen wollen"],
      "Gute Formulierung: „Wir nutzen ausschließlich unser Lager. Da wir selbst als Verkäufer auftreten und an die SLAs gebunden sind, benötigen wir hier die Kontrolle über das Fulfillment.“", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t28-05", "Ein Kunde sagt: \"Marktplätze anbinden können wir auch selbst.\" Was ist die beste Reaktion?",
      ["Den Mehrwert benennen, den er selbst nicht hat: Verkauf im eigenen Namen ohne eigene Registrierungen im Ausland, Content, profitable Preise je Marktplatz, internationale Kanäle", "Ihm erklären, dass er das nicht kann", "Das Gespräch beenden", "Auf Sorgen eingehen, die er gar nicht geäußert hat"],
      "Genau der Verkauf im eigenen Namen ist für viele Marken der Hebel, weil sie sich dann nicht im Ausland registrieren müssen.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t28-06", "Ein Kunde fragt: \"Wer bestimmt die Preise?\" Was antwortest du?",
      ["Die Marke gibt die Preisstrategie vor: UVP und auf Wunsch Preisgrenzen. HBOD schlägt darin Preise je Marktplatz vor. Aktionen nur in Abstimmung.", "HBOD bestimmt alles allein", "Der Marktplatz bestimmt alles", "Die Preise sind überall gleich"],
      "Preiskontrolle ist ein Kernargument gegenüber Händlern, die eigenmächtig Preise senken.", quelle="Deine Zusammenfassung"),
    S("t28-09", "Ein Interessent schlägt vor: „Wir geben nur einen festen Netto-Abgabepreis vor, den Rest kalkuliert ihr.“ Was für ein Modell ist das?",
      ["Ein Wholesale- bzw. Händlermodell: HBOD würde die Ware zu einem festen Preis einkaufen und selbst kalkulieren", "Genau das bestehende HBOD-Modell", "Dropshipping", "Ein Werbemodell"],
      "Das passt nicht direkt zu HBODs Kommissionsmodell. Ob HBOD so etwas für ausgewählte Sortimente macht, entscheidet die Geschäftsführung.", quelle="Erfahrung aus Kundenmails (anonymisiert)", hinweis="Vor einer Antwort intern klären"),
    S("t28-10", "Ein Kunde stellt in einer Mail drei Fragen. Was ist bei deiner Antwort am wichtigsten?",
      ["Auf seine Fragen eingehen und kurz bleiben, statt gegen Sorgen zu argumentieren, die er gar nicht geäußert hat", "Möglichst lange Mails schreiben und alles erklären", "Nie Zahlen nennen", "Nie eine Kalkulation schicken"],
      "Gute Antworten beantworten jede Frage direkt und enden mit einem Terminangebot.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    T("t28-11", "Ein Kunde schreibt: \"8,06 € pro Artikel sind uns zu wenig, beim Fachhandel bekommen wir mehr.\" Schreibe eine kurze Antwort (3 bis 6 Sätze).",
      "Danke für die offene Rückmeldung, das verstehe ich. Die Beispielrechnung war bewusst vorsichtig mit 20 % Retouren und 1,2 Artikeln pro Warenkorb. Bei Herrenunterwäsche liegen die Werte eher bei 8 bis 10 % und 1,5 bis 2 Artikeln, dann steigt die Auszahlung deutlich. Mit Multipacks und Bundles senken wir zusätzlich die Logistikkosten pro Artikel. Wenn Sie uns Ihre gewünschte Mindestauszahlung nennen, rechnen wir je Marktplatz den nötigen Verkaufspreis aus. Wir wollen den Fachhandel dabei ergänzen, nicht ersetzen. Wollen wir das in einem kurzen Termin durchgehen?",
      ["Verständnis für den Einwand zeigen", "Erklären, dass die Rechnung bewusst konservativ war", "Mindestens einen Hebel nennen (realistischere Retourenquote/Artikel pro Warenkorb, Multipacks/Bundles, Preis je Marktplatz)", "Mindestauszahlung erfragen und Rückwärtsrechnung anbieten", "HBOD als Ergänzung zum Fachhandel einordnen", "Mit einem konkreten nächsten Schritt enden"],
      erklaerung="", quelle="Erfahrung aus Kundenmails (anonymisiert)", mail=True),
    T("t28-12", "Ein Kunde schreibt: \"Unsere eigene Logistik ist viel günstiger als eure.\" Formuliere eine kurze, sachliche Antwort (3 bis 5 Sätze).",
      "Danke für den Hinweis, das nehme ich ernst. Unsere Logistikwerte beziehen sich auf den ganzen Warenkorb und enthalten Picking, Verpackung, Wareneingang und Lager. Über unser Volumen haben wir sehr gute Konditionen bei DHL, und alle Positionen stehen transparent in unserer Preisliste. Mit Multipacks und Bundles senken wir die Kosten pro Artikel zusätzlich deutlich. Gern rechne ich Ihnen das an einem Ihrer Artikel konkret vor.",
      ["Sachlich und ohne Abwertung der Kundenlogistik antworten", "Erklären, was in den Logistikkosten enthalten ist (je Warenkorb)", "DHL-Konditionen durch das Volumen und die transparente Preisliste nennen", "Hebel nennen: Bundles und Multipacks", "Konkretes Angebot zum Nachrechnen machen"],
      erklaerung="Vermeide Sätze wie \"Die Logistik berechnen wir zu unseren Kosten\" oder \"Wir verdienen an der Logistik nichts\". Das klingt vertrieblich schlecht.", quelle="Erfahrung aus Kundenmails (anonymisiert), Deine Mail-Regeln", mail=True),
],
    punkte=["Ruhig einordnen, fair vergleichen und einen Hebel anbieten.", "Provision: erklären, was sie abdeckt (Aufschaltung, Content, Preise, Service, Steuer, Kampagnen), keine Fixkosten, HBOD verdient nur bei Erfolg.", "Logistik: Die Werte gelten je Warenkorb. Bundles und Multipacks senken die Kosten pro Artikel. Nie „zu unseren Kosten“ sagen.", "Fachhandel: HBOD ergänzt, statt zu ersetzen.", "Eigenes Lager: Für die HBOD-Kanäle nein, weil HBOD als Verkäufer an die SLAs der Marktplätze gebunden ist."],
    merksatz="Verstehen, einordnen, Hebel anbieten.",
    quelle="Erfahrung aus Kundenmails (anonymisiert), Deine Mail-Regeln")

stapel("t29", "E", "E-Mails an Kunden",
    "Regeln für gute Antworten und echte Übungsfälle mit Bewertung.", [
    M("t29-01", "Welche Regeln machen eine Kundenmail gut? Kreuze alles Richtige an.",
      ["Jede Frage des Kunden beantworten", "Ehrlich trennen: Was weiß ich, was prüfe ich, was kann ich nicht einschätzen", "Nichts zusagen, was noch nicht geprüft ist", "Details im Termin vertiefen statt alles in die Mail zu packen", "Mit einem klaren nächsten Schritt enden"],
      ["Möglichst viele Anhänge mitschicken", "Marktplätze versprechen, auf denen HBOD nur technisch angebunden ist"],
      "Das sind die wichtigsten Lektionen aus echten Kundenmails.", quelle="Erfahrung aus Kundenmails (anonymisiert), Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    S("t29-02", "Der Kunde schreibt dich mit \"Du\" und \"Euch\" an. Wie antwortest du?",
      ["Die Anrede spiegeln und ebenfalls duzen", "Immer siezen, egal was der Kunde schreibt", "Abwechselnd duzen und siezen", "Gar keine Anrede verwenden"],
      "Wer selbst duzt, freut sich meist über ein Du zurück.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    M("t29-03", "Womit beginnt eine Erstantwort an einen Interessenten? Kreuze alles an, was in den kurzen Pitch gehört.",
      ["Ein Vertrag für alle Kanäle", "Über 40 Marktplätze", "Über 30 Länder", "Wir übernehmen das operative Geschäft", "Fulfillment aus unserem Lager"],
      ["Alle Positionen der Preisliste", "Der komplette Mustervertrag"],
      "So beginnen Erstantworten nach deiner Mail-Regel. Details wie Preise kommen später oder im Gespräch.", quelle="Deine Mail-Regeln"),
    S("t29-04", "Ein Kunde fragt nach Galeries Lafayette. Die Chancen auf Freigabe sind gering. Was schreibst du?",
      ["Eine ehrliche Einschätzung (Chancen gering) und gute Alternativen wie GALERIA oder andere Kanäle", "\"Kein Problem, wir sind dort angebunden.\"", "Gar nichts zu dieser Frage", "\"Das klappt sicher.\""],
      "Ehrliche Einschätzungen schaffen Vertrauen, auch wenn sie nicht nach Verkauf klingen.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t29-05", "Ein Kunde fragt: \"Erfolgt der Vertrieb in unserem Namen und auf unsere Rechnung?\" Was ist die richtige Kurzantwort?",
      ["Nein. Wir verkaufen im eigenen Namen und auf eigene Rechnung. Die Ware bleibt bis zum Verkauf Ihr Eigentum, abgerechnet wird monatlich per Gutschrift.", "Ja, wir verkaufen in Ihrem Namen", "Das ist bei jedem Marktplatz anders", "Das darf ich nicht sagen"],
      "\"Wir treten als Verkäufer auf\" allein ist zu ungenau.", quelle="Erfahrung aus Kundenmails (anonymisiert)"),
    S("t29-07", "Wie nennst du die HBOD-Provision in einer Kundenmail?",
      ["10 bis 12 % je nach Umsatz", "12 %, aber verhandelbar", "Je nach Kunde zwischen 5 und 20 %", "Gar nicht, das steht erst im Vertrag"],
      "Die Staffel lautet 12 % bis 100.000 € Monatsumsatz, darüber 10 %. In Mails reicht die kurze Form.", quelle="Deine Mail-Regeln, Einweisung Produktkalkulation"),
    S("t29-08", "Du sagst einem Kunden zu, etwas intern zu klären. Was gehört dazu?",
      ["Ein konkretes Datum nennen, bis wann du dich meldest, und es einhalten", "\"Ich melde mich irgendwann.\"", "Nichts, der Kunde fragt schon nach", "Die Frage an den Kunden zurückgeben"],
      "Verlässlichkeit ist im Key Account Management die halbe Miete.", quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
    M("t29-10", "Was brauchst du für eine konkrete Kalkulation von einem Kunden? Kreuze alles Richtige an.",
      ["Artikel mit UVP oder Verkaufspreis", "Kategorie bzw. Zielgruppe (Damen, Herren, Kinder)", "Eine Referenz zur Retourenquote", "Gewünschte Mindestauszahlung"],
      ["Die privaten Kontaktdaten der Mitarbeiter", "Die Passwörter der Marktplatzkonten"],
      "Ø Artikel pro Bestellung und Maße helfen zusätzlich.", quelle="Gespräch mit Kollegen (Erfahrungswert), Erfahrung aus Kundenmails (anonymisiert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    T("t29-11", "Eine neue Kinderbekleidungsmarke (rund 60 Artikel, verkauft selbst auf OTTO) schreibt: \"Welche Marktplätze empfehlen Sie uns und was kostet uns das?\" Schreibe eine Antwort (höchstens 10 Sätze).",
      "Guten Tag Frau Muster, vielen Dank für Ihre Nachricht. Mit einem Vertrag verkaufen wir Ihre Produkte auf über 40 Marktplätzen in über 30 Ländern und übernehmen das komplette operative Geschäft bis zum Fulfillment. Für Kinderbekleidung sehen wir Potenzial vor allem dort, wo Sie noch nicht vertreten sind, zum Beispiel ABOUT YOU, bol für die Benelux-Länder und Galaxus für die Schweiz. Eine genaue Empfehlung gebe ich Ihnen gern, sobald ich Ihr Sortiment und Ihre Preise kenne. Wir arbeiten rein erfolgsbasiert ohne Onboarding- oder Fixkosten: Unsere Provision liegt bei 10 bis 12 % je nach Umsatz, die Marktplatzprovisionen geben wir 1:1 weiter, die Logistik läuft nach unserer Preisliste. Im Anhang finden Sie unsere Unternehmenspräsentation. Für eine Beispielkalkulation bräuchte ich Ihre UVPs und, falls vorhanden, Ihre Retourenquote auf OTTO. Gern schicke ich Ihnen weitere Infos, oder wir sprechen persönlich. Beste Grüße",
      ["Freundlicher Einstieg mit Dank", "Kurzer Pitch: ein Vertrag, über 40 Marktplätze, über 30 Länder, operatives Geschäft", "Marktplätze begründet nach Potenzial nennen oder vom Sortiment abhängig machen, keine Pauschalversprechen", "Kosten korrekt: erfolgsbasiert, keine Fixkosten, Provision 10 bis 12 % je nach Umsatz, Marktplatzprovision 1:1, Logistik nach Preisliste", "Unternehmenspräsentation als Anhang nennen", "Benötigte Daten erfragen (UVP, Retourenquote z. B. von OTTO)", "Abschluss: weitere Infos oder persönliches Gespräch anbieten"],
      erklaerung="", quelle="Erfahrung aus Kundenmails (anonymisiert), Unternehmenspräsentation 2026", mail=True),
    T("t29-12", "Ein Bestandskunde schreibt im Januar: \"Warum ist meine Auszahlung diesen Monat so niedrig?\" Schreibe eine Antwort (höchstens 8 Sätze).",
      "Hallo Herr Muster, danke für Ihre Nachricht, ich verstehe, dass Sie das überrascht. Der Hauptgrund ist der Zeitversatz bei den Retouren: Die starken Verkäufe aus November und Dezember kommen teilweise erst jetzt zurück und werden im Januar gebucht, während der Januar selbst weniger Umsatz bringt. Dadurch sieht dieser Monat schwächer aus, als Ihr Geschäft tatsächlich läuft. Aussagekräftiger ist der Durchschnitt über mehrere Monate, und der liegt im erwarteten Bereich. Gern gehe ich die Zahlen in einem kurzen Termin mit Ihnen durch. Beste Grüße",
      ["Verständnis zeigen", "Ursache Retourenzeitversatz nach starkem November/Dezember erklären", "Einordnen: Durchschnitt über mehrere Monate betrachten", "Zahlen oder Termin anbieten", "Ruhiger, sachlicher Ton ohne Schuldzuweisung"],
      erklaerung="", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen.", mail=True),
    T("t29-13", "Eine Marke meldet falsche Produktdaten bei Galaxus (falscher Titel, falsche Beschreibung, Fehler bei mehreren Farben). Schreibe eine kurze erste Antwort (höchstens 6 Sätze).",
      "Hallo Frau Muster, vielen Dank für Ihren Hinweis und die Beispiele. Ich habe das an unser Team für die Produktdaten weitergegeben. Wir korrigieren die genannten Artikel und prüfen dabei die ganze Style-Familie, damit auch die anderen Farben und Größen stimmen. Außerdem klären wir, warum es bei Galaxus zu den Abweichungen kam. Ich melde mich bis Freitag mit dem Stand bei Ihnen. Beste Grüße",
      ["Dank und Eingangsbestätigung", "Konkrete Maßnahme: Weitergabe an das zuständige Team bzw. Ticket", "Ganze Style-Familie prüfen, nicht nur den einen Artikel", "Ursache klären", "Rückmeldung mit Zeitpunkt zusagen"],
      erklaerung="", quelle="Kundenfall (anonymisiert)", mail=True),
    S("t29-14", "Welcher Satz gehört nicht in eine Kundenmail?",
      ["\"Die Logistikkosten berechnen wir zu unseren Kosten.\"", "\"Wir arbeiten rein erfolgsbasiert.\"", "\"Über unser Volumen haben wir sehr gute Konditionen bei DHL.\"", "\"Gern schicke ich Ihnen weitere Infos, oder wir sprechen persönlich.\""],
      "Der Satz klingt vertrieblich schlecht. Besser: sehr gute DHL-Konditionen durch unser Volumen und eine transparente Preisliste.", quelle="Deine Mail-Regeln"),
    S("t29-15", "Welchen Anhang nennst du in einer Erstantwort?",
      ["Die Unternehmenspräsentation", "Preisliste und Mustervertrag", "Die komplette Excel-Kalkulation mit allen Blättern", "Die Abrechnung eines anderen Kunden"],
      "So lautet deine Regel für Erstantworten. Preisliste und Mustervertrag schickst du erst später, wenn es konkret wird.", quelle="Deine Mail-Regeln"),
    S("t29-16", "Wie endet eine Erstantwort?",
      ["Mit dem Angebot, auf Wunsch weitere Infos zu schicken oder persönlich zu sprechen", "Mit einer Frist, bis wann der Kunde unterschreiben muss", "Mit der kompletten Preisliste im Text", "Ohne Gruß und ohne nächsten Schritt"],
      "Kurz halten und die Tür öffnen. Ein persönliches Gespräch klärt Details besser als eine lange Mail.", quelle="Deine Mail-Regeln"),
],
    punkte=["Erstantwort: Pitch zuerst (ein Vertrag, über 40 Marktplätze, über 30 Länder, operatives Geschäft, Fulfillment aus unserem Lager).", "Provision in Mails: „10 bis 12 % je nach Umsatz“. Anhang: die Unternehmenspräsentation.", "Jede Frage beantworten, ehrlich trennen (weiß ich, prüfe ich, kann ich nicht einschätzen), nichts Ungeprüftes zusagen.", "Anrede spiegeln. Wer etwas klären will, nennt ein Datum und hält es ein.", "Am Ende weitere Infos oder ein persönliches Gespräch anbieten. Nie „Logistik zu unseren Kosten“."],
    merksatz="Kurz, ehrlich, mit klarem nächsten Schritt.",
    quelle="Deine Mail-Regeln, Erfahrung aus Kundenmails (anonymisiert)")

stapel("t30", "E", "Bestandskunden betreuen",
    "Beziehungspflege, Rhythmus, proaktive Themen und schwierige Situationen.", [
    S("t30-01", "Was ist der Kern der Account-Pflege laut deinem Kollegen?",
      ["Beziehungspflege: Entwicklung erklären, E-Commerce-Basics vermitteln, immer eine Antwort geben", "Möglichst oft Rechnungen schicken", "Nur bei Problemen anrufen", "Dem Kunden neue Verträge verkaufen"],
      "Viele Kunden haben wenig E-Commerce-Wissen. Das Gefühl, einen Experten an der Seite zu haben, ist viel wert.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-02", "Wie oft erinnerst du einen Kunden an offene Punkte wie fehlende Bilder?",
      ["Dosiert, etwa alle zwei Wochen freundlich, ohne zu nerven", "Jeden Tag", "Nie", "Einmal im Jahr"],
      "Nachhalten ja, aber mit Fingerspitzengefühl.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-03", "Welches Argument motiviert Kunden, fehlende Daten zu liefern?",
      ["\"Wir könnten schon das Doppelte verdienen, wenn wir X von dir hätten.\"", "\"Sonst kündigen wir.\"", "\"Das ist Pflicht laut Vertrag.\"", "\"Alle anderen Kunden sind schneller.\""],
      "Fehlende Daten sind entgangener Umsatz. Das ist für die Marke greifbar.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-04", "Wie oft hat der erfahrene Kollege Kontakt zu seinen Kunden?",
      ["Mit fast allen mindestens einmal im Monat, mit manchen wöchentlich. Dazu die Monatsabrechnung per Mail.", "Ein Termin pro Jahr", "Nur schriftlich, nie telefonieren", "Täglich zwei Stunden Call"],
      "Einen festen Rhythmus für alle gibt es nicht. Bei einem Bestandskunden war der nächste Call z. B. in zwei Wochen angesetzt. Zwischendurch bist du erreichbar.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-05", "Ein Neukunde prüft seine Zahlen jede Woche. Was bedeutet das?",
      ["Das Vertrauen muss im Tagesgeschäft noch wachsen. Ein Vertrag allein reicht nicht.", "Der Kunde will kündigen", "Der Kunde misstraut HBOD grundsätzlich", "Das ist ein Fehler im System"],
      "\"In der Beziehung macht man nach einem Monat auch keinen Antrag.\"", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    M("t30-06", "Welche Themen solltest du proaktiv ansprechen? Kreuze alles Richtige an.",
      ["Black Friday und Cyber Week", "Saisonware, Retagging und Season Cleaning", "Verspätete Abrechnungen", "Ladenhüter und drohendes Langzeitlager", "Defektware: Spende oder Rücksendung"],
      ["Private Urlaubspläne des Kunden", "Gehälter bei HBOD"],
      "Proaktiv heißt: bevor der Kunde fragt.", quelle="Gespräch mit Kollegen (Erfahrungswert), Preisliste 10/2026", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-07", "Du siehst, dass die nächste Abrechnung eines Kunden schwach wird. Was tust du?",
      ["Vorher anrufen oder schreiben, Ergebnis und Ursache erklären und einordnen, ob Handlungsbedarf besteht", "Abwarten, ob der Kunde es merkt", "Die Abrechnung verzögern", "Dem Lager die Schuld geben"],
      "Proaktives Warnen ist einer der wichtigsten Vertrauensbausteine.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-08", "Was passiert mit defekter Ware?",
      ["Sie wird gespendet, entsorgt oder an die Marke zurückgeschickt", "HBOD verkauft sie heimlich weiter", "Sie bleibt für immer im Lager", "Der Endkunde behält sie"],
      "Laut Gespräch wird einmal im Quartal gespendet. Pro Artikel kostet das laut Preisliste 0,29 €.", quelle="Gespräch mit Kollegen (Erfahrungswert), Preisliste 10/2026", hinweis="Ablauf bei Defektware intern bestätigen."),
    S("t30-09", "Die Top-Seller einer Marke laufen bei HBOD schlechter als erwartet. Was ist der Rat?",
      ["Breit starten und auswerten, weil bei Basics oft Preiskonkurrenz herrscht und exklusive Artikel besser laufen können", "Nur noch die Top-Seller listen", "Die Preise aller Artikel halbieren", "Den Kunden kündigen"],
      "Die Zahlen bei HBOD können anders aussehen als im eigenen Shop der Marke.", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-10", "Wie sieht die monatliche Routine eines guten Key Account Managers aus?",
      ["Die Liste jeder Marke durchgehen, Auffälligkeiten (positiv wie negativ) suchen und dann ins Detail gehen", "Nur die größte Marke anschauen", "Gar nichts, die Abrechnung läuft automatisch", "Alle Kunden gleichzeitig anrufen"],
      "Fragen: Liegt es an einem Marktplatz, am Sortiment, an einer Aktion, an der Retourenquote?", quelle="Gespräch mit Kollegen (Erfahrungswert)", hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen."),
    S("t30-11", "Ein Kunde stellt eine Frage, die du nicht beantworten kannst. Was tust du?",
      ["Ehrlich sagen, dass du es intern klärst, und einen Zeitpunkt für die Antwort nennen", "Irgendetwas antworten, damit es kompetent klingt", "Die Frage überhören", "Den Kunden an den Marktplatz verweisen"],
      "Falsche Antworten kosten Vertrauen. Ein \"Ich kläre das bis Donnerstag\" nicht.", quelle="Einarbeitungs-Chat", hinweis="Aus dem Einarbeitungs-Chat. Intern bestätigen."),
],
    punkte=["Kern der Betreuung ist Beziehungspflege: Entwicklung erklären, E-Commerce-Basics vermitteln, immer eine Antwort geben.", "Proaktiv melden, bevor der Kunde fragt: schwache Abrechnungen, Black Friday, Season Cleaning, Ladenhüter, verspätete Abrechnungen.", "Fehlende Daten dosiert nachhalten, etwa alle zwei Wochen, mit dem Argument entgangener Umsatz.", "Monatlich die Liste jeder Marke durchgehen und Auffälligkeiten suchen, positiv wie negativ."],
    merksatz="Proaktiv statt reaktiv.",
    quelle="Gespräch mit Kollegen (Erfahrungswert)",
    hinweis="Erfahrungswert aus einem Gespräch. Intern bestätigen.")

stapel("t31", "E", "Auftreten in Gesprächen",
    "Sicher auftreten, auch mit Geschäftsführern und anderen \"hohen Tieren\".", [
    S("t31-01", "Was ist die wichtigste Erkenntnis gegen die Angst vor \"hohen Tieren\"?",
      ["Die gefühlte Hierarchie entsteht vor allem im eigenen Kopf. Ranghohe Menschen schätzen Augenhöhe mehr als Unterwürfigkeit.", "Man sollte ranghohe Menschen meiden", "Man sollte möglichst wenig sagen", "Man sollte immer zustimmen"],
      "Viele Führungskräfte sind von Ja-Sagern umgeben. Eine fundierte eigene Meinung fällt positiv auf.", quelle="Deine Notizen"),
    S("t31-02", "Welche innere Haltung hilft vor einem wichtigen Gespräch?",
      ["Vom Prüfling zum Partner: Es ist ein professioneller Austausch mit gemeinsamem Interesse, keine Prüfung", "Ich werde bewertet und muss perfekt sein", "Ich muss den anderen beeindrucken", "Ich darf keine Fehler machen"],
      "Du gehst mit einem Angebot hinein, das dem Gegenüber helfen kann.", quelle="Deine Notizen"),
    S("t31-03", "Was ist eine 3-Satz-Kernbotschaft?",
      ["Du weißt vorher genau, warum du da bist und was dein Ziel ist, in drei Sätzen", "Du sagst im ganzen Gespräch nur drei Sätze", "Du liest drei Folien vor", "Du stellst drei Fragen"],
      "Eine klare Kernbotschaft schützt vor dem Blackout.", quelle="Deine Notizen"),
    S("t31-04", "Wie bereitest du dich auf ein Gespräch mit einem Geschäftsführer vor?",
      ["Recherche: aktuelle Projekte, Sortiment, Kanäle und Aussagen der Firma kennen", "Gar nicht, spontan wirkt ehrlicher", "Nur die eigene Präsentation auswendig lernen", "Den Lebenslauf des Gegenübers auswendig lernen"],
      "Zu wissen, wie das Gegenüber tickt, nimmt der Situation das Unbekannte.", quelle="Deine Notizen"),
    S("t31-05", "Was hilft beim \"Worst-Case-Szenario durchspielen\"?",
      ["Zu merken, dass das Schlimmste meist ein holpriger Satz oder kurzes Schweigen ist, und das ist menschlich", "Sich alle Katastrophen genau auszumalen", "Das Gespräch abzusagen", "Einen Kollegen allein gehen zu lassen"],
      "Ein holpriger Satz ruiniert keine Karriere.", quelle="Deine Notizen"),
    S("t31-06", "Was ist die \"Atem-Bremse\"?",
      ["Doppelt so lange aus- wie einatmen, z. B. 4 Sekunden ein, 8 Sekunden aus", "Die Luft möglichst lange anhalten", "Schnell und flach atmen", "Durch den Mund ein- und ausatmen"],
      "Langes Ausatmen beruhigt das Nervensystem und senkt den Puls.", quelle="Deine Notizen"),
    S("t31-07", "Warum sollst du bewusst langsam sprechen?",
      ["Weil es kompetent wirkt und dir Zeit zum Denken gibt", "Weil der andere sonst einschläft", "Weil schnelles Sprechen verboten ist", "Weil man dann weniger sagen muss"],
      "Nervosität macht schnell. Pausen wirken souverän.", quelle="Deine Notizen"),
    S("t31-08", "Wie baust du die Angst Schritt für Schritt ab?",
      ["Die Komfortzone dehnen: bewusst kleinere Übungsgespräche suchen, z. B. Fragen in Runden stellen", "Große Gespräche konsequent vermeiden", "Nur noch per Mail kommunizieren", "Warten, bis die Angst von selbst weggeht"],
      "Je öfter du dich der Situation aussetzt, desto mehr Routine entwickelt dein Gehirn.", quelle="Deine Notizen"),
    S("t31-09", "Im Kundentermin spricht dich der Kunde direkt an. Was tust du?",
      ["Selbst antworten, statt dass der Kollege einspringt", "Sofort zum Kollegen schauen", "Schweigen", "Das Thema wechseln"],
      "Das hat der Kollege dir für künftige Termine ausdrücklich mitgegeben.", quelle="Einarbeitung"),
    T("t31-11", "Formuliere deine 3-Satz-Kernbotschaft für ein Erstgespräch mit dem Geschäftsführer einer Wäschemarke.",
      "HBOD ist ein Full-Service-Partner, der Ihre Ware im eigenen Namen auf über 40 Marktplätzen in Europa verkauft, von den Produktseiten über den Versand bis zum Kundenservice. Sie behalten die Kontrolle über Preise und Markenauftritt, sehen alle Zahlen transparent und zahlen keine Fixkosten, weil wir nur am erfolgreichen Verkauf verdienen. Heute möchte ich verstehen, ob unser Modell zu Ihrem Sortiment passt, und Ihnen an einem Beispiel zeigen, was bei Ihnen ankommen würde.",
      ["Was HBOD ist: Full-Service, Verkauf im eigenen Namen, viele Marktplätze", "Nutzen für die Marke: Reichweite ohne Aufwand, Kontrolle über Preis und Marke, Transparenz", "Erfolgsbasiert ohne Fixkosten", "Ziel des Gesprächs: Passung prüfen und nächster Schritt"],
      erklaerung="", quelle="Deine Notizen, Unternehmenspräsentation 2026"),
],
    punkte=["Die gefühlte Hierarchie entsteht vor allem im eigenen Kopf. Ranghohe Menschen schätzen Augenhöhe.", "Vorbereitung: Recherche zum Gegenüber und eine Kernbotschaft in drei Sätzen.", "Gegen Nervosität: doppelt so lange aus- wie einatmen, bewusst langsam sprechen.", "Was du nicht weißt, ehrlich sagen und verbindlich nachliefern."],
    merksatz="Vom Prüfling zum Partner.",
    quelle="Deine Notizen")
